301	Future<List<AccountSettingsState>> _emittedDuring(
302	  AccountSettingsCubit cubit,
303	  Future<void> Function() act,
304	) async {
305	  final emitted = <AccountSettingsState>[];
306	  final subscription = cubit.stream.listen(emitted.add);
307	  await act();
308	  // `pumpEventQueue()` (not a single `Future.delayed(Duration.zero)`): the
309	  // `biometricEnabled` mirror travels repository -> Stream.multi's own
310	  // forwarding subscription -> cubit's `emit()` -> `_stateController`,
311	  // several microtask hops deep — one `Duration.zero` delay only guarantees
312	  // draining one hop, leaving a later hop's delivery to land after this
313	  // helper already returned.
314	  await pumpEventQueue();
315	  await subscription.cancel();
316	  return emitted;
317	}
