447	/// Story 8.4 (review finding) — the "Sair" group's own router: two routes
448	/// (`/configuracoes`, `/vault`) plus a minimal AD-14-style gate (`redirect`
449	/// away from `/configuracoes` whenever [vaultRepository] isn't
450	/// [VaultStatus.unlocked], re-evaluated on every [VaultRepository.
451	/// statusStream] emission) — just enough to prove `VaultRepository.lock()`
452	/// actually drives this router to `/vault`, without pulling in the real
453	/// `buildAppRouter()`'s full `sl` DI graph (every other route it declares
454	/// needs cubits this suite has no reason to resolve).
455	GoRouter _routerWithVaultGate(
456	  Widget screen,
457	  VaultRepository vaultRepository,
458	) {
459	  return GoRouter(
460	    initialLocation: AppRoutePaths.configuracoes,
461	    refreshListenable: _StreamRefreshListenable(vaultRepository.statusStream),
462	    redirect: (context, state) {
463	      if (vaultRepository.currentStatus != VaultStatus.unlocked) {
464	        return state.matchedLocation == AppRoutePaths.vaultLock
465	            ? null
466	            : AppRoutePaths.vaultLock;
467	      }
468	      return null;
469	    },
470	    routes: [
471	      GoRoute(
472	        path: AppRoutePaths.vaultLock,
473	        builder: (context, state) => const Text('Vault'),
474	      ),
475	      GoRoute(path: AppRoutePaths.configuracoes, builder: (context, state) => screen),
476	    ],
477	  );
478	}
