480	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
481	/// pair and pumps the real screen around it, registering both for cleanup.
482	///
483	/// Deliberately constructed *inside* each `testWidgets` body (via this
484	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
485	/// `package:test`'s own per-test zone, a different zone than the one
486	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
487	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
488	/// subscription to the repository's stream, set up in its constructor)
489	/// created in that outer zone does not reliably get its pending events
490	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
491	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
492	/// widget never rebuilt, no matter how many `pump()` calls followed.
493	/// Constructing the cubit here, inside the same zone `tester.pump()`
494	/// drains, avoids the mismatch entirely.
495	Future<(_FakeAccountSettingsRepository, AccountSettingsCubit)> _pumpScreen(
496	  WidgetTester tester,
497	) async {
498	  final fakeRepository = _FakeAccountSettingsRepository();
499	  final cubit = _buildAccountSettingsCubit(fakeRepository);
500	  addTearDown(() => cubit.close());
501	  addTearDown(fakeRepository.dispose);
502	
503	  final router = _routerWith(
504	    AccountSettingsScreen(
505	      cubit: cubit,
506	      dashboardCubit: _buildDashboardCubit(),
507	      narrativeCubit: _buildNarrativeCubit(),
508	    ),
509	  );
510	  addTearDown(router.dispose);
511	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
512	
513	  return (fakeRepository, cubit);
514	}
